def minimum_keyboard_screen_sequence(target):
    screen='';answer=[]
    for wanted in target:
        screen+='a';answer.append(screen)
        while screen[-1]!=wanted:
            screen=screen[:-1]+chr(ord(screen[-1])+1);answer.append(screen)
    return answer

